window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[171]={"id":"171","numero":171,"titre":"Gale & Pédiculoses","objectifs":[{"id":"171-1","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les modes de transmission principaux et l’épidémiologie de la gale et des pédiculoses","contenu":"<div class=\"notion-course\"><p>La <span>gale</span> est une <span><span class=\"nc-red nc-bold\">ectoparasitose</span> humaine</span>\n      responsable d'une dermatose fréquente, <strong><span class=\"nc-red nc-bold\">endémo-épidémique mondiale</span> en recrudescence</strong>.\n      L'<strong>homme est le seul réservoir</strong>. <span>Les</span> <span>pédiculoses</span> sont des\n      ectoparasitoses <strong>strictement humaines et <span class=\"nc-red nc-bold\">ubiquitaires</span></strong>.</p>\n      <table>\n        <thead>\n          <tr><th>Entité</th><th>Transmission directe</th><th>Transmission indirecte</th><th><span>Terrain</span> / contexte</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Gale</span></strong></td>\n            <td><span>Interhumaine ++</span> : 1 <span><span class=\"nc-green_bg nc-bold\">contact</span></span> suffit ; contacts intimes et prolongés (familial, couple)</td>\n            <td><span>Rare</span> (linge, literie) — sauf formes <span><span class=\"nc-orange_bg\">profuses</span></span><span class=\"nc-orange_bg\"> et </span><span><span class=\"nc-orange_bg\">hyperkératosiques</span></span></td>\n            <td>Collectivités médicalisées, foyers de personnes âgées, milieux défavorisés, <span class=\"nc-orange_bg\">immunodéprimés</span> ; <span>gale</span> du <strong><span class=\"nc-red nc-bold\">pubis</span> = <span><span class=\"nc-red nc-bold\">IST</span></span></strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Pédiculose</span> du cuir chevelu</strong></td>\n            <td><span>Interhumaine ++</span> (<span>contact</span> des têtes)</td>\n            <td>Possible (bonnets, peignes, brosses)</td>\n            <td><strong><span class=\"nc-red nc-bold\">Collectivités d'enfants</span></strong> en milieu scolaire — <strong>tous <span>les</span> milieux sociaux</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Pédiculose corporelle</strong></td>\n            <td><span>Interhumaine</span></td>\n            <td><span>++</span> (vêtements)</td>\n            <td><span>Marqueur de <span class=\"nc-red nc-bold\">précarité</span></span> : camps de réfugiés, prisons, SDF (<span class=\"nc-red nc-bold\">manque d'hygiène</span> + <span class=\"nc-red nc-bold\">froid</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Phtiriase pubienne</strong></td>\n            <td><span>Sexuelle</span></td>\n            <td>—</td>\n            <td><strong><span>IST</span></strong> — penser au <span>dépistage</span> des autres IST</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span>IST</span> · 59 — Sujet en situation de précarité</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la gale","contenu":"<div class=\"notion-course\"><p>Agent : <span>Sarcoptes scabiei var. hominis</span>, un <strong>acarien</strong>.\n      Ce sont <span>les</span> <strong><span class=\"nc-red nc-bold\">femelles</span></strong> qui sont responsables de la maladie.</p>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>Mobilité</td><td>Déplacement de <span>plusieurs cm/h</span> à la surface de la peau ; bonne mobilité à <span>25-30 °C</span>, perte de mobilité <span><span class=\"nc-red nc-bold\">&lt; 20 °C</span></span></td></tr>\n          <tr><td>Destruction thermique</td><td>Survie hors de l’hôte : plusieurs jours possibles, selon température et humidité ; appliquer le protocole de décontamination adapté.</td></tr>\n          <tr><td>Incubation</td><td><span>≈ 3 semaines</span> — plus courte si réinfestation (<span>5 j à 1 mois</span>)</td></tr>\n          <tr><td>Cycle <span>parasitaire</span></td><td><span>≈ <span class=\"nc-pink nc-bold\">20 jours</span></span></td></tr>\n          <tr><td>Charge <span>parasitaire</span></td><td><span>10-20 <span class=\"nc-red nc-bold\">femelles</span></span> par individu (<span>gale</span> commune)</td></tr>\n        </tbody>\n      </table>\n      <p>Le mécanisme se déroule en trois temps :</p>\n      <ul>\n        <li>La <strong><span class=\"nc-pink nc-bold\">femelle</span></strong> creuse un <span>tunnel (sillon)</span> dans la <span>couche cornée</span> de l'épiderme et y <strong>pond ses <span class=\"nc-blue_bg\">œufs</span></strong>.</li>\n        <li>La <span><span class=\"nc-yellow_bg\">réaction urticarienne</span></span> de l'hôte est responsable du <strong><span><span class=\"nc-red nc-bold\">prurit</span></span></strong>.</li>\n        <li>Le grattage expose au <span class=\"nc-red_bg\">risque de</span> <span><span class=\"nc-red_bg nc-bold\">surinfection bactérienne</span></span>.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les différents agents des pédiculoses","contenu":"<div class=\"notion-course\"><p>Les <span class=\"nc-purple nc-bold\">poux</span> de tête et du pubis restent attachés à leurs sites pileux ; le pou de corps vit surtout dans les vêtements et gagne la peau pour se nourrir.</p>\n      <table>\n        <thead><tr><th>Espèce</th><th>Nom courant</th><th>Localisation / mobilité</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-purple_bg\">Pediculus humanus capitis</span></span></td><td>Pou de tête</td><td>Cuir chevelu — <strong>très mobile</strong></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Pediculus humanus corporis</span></span></td><td>Pou de corps</td><td>Corps ; se réfugie dans <span>les</span> vêtements — <strong>très mobile</strong></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Phtirus pubis</span></span> (<span class=\"nc-purple_bg\">Phtirius inguinalis</span>)</td><td>Pou du pubis / <span>morpion</span></td><td>Région génitale — <strong>vit accroché aux poils</strong> (immobile)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/171/poux-comparatif.png\" alt=\"Schéma comparatif des trois poux humains : pou de tête, pou de corps allongé, pou du pubis trapu en forme de crabe\" loading=\"lazy\">\n        <figcaption><span>Les</span> trois poux humains : le pou de tête et le pou de corps ont un corps allongé, le pou du pubis a un corps trapu et ramassé (« en crabe »). Source : fiche source EDN item 171 (Collège de dermatologie).</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span>IST</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes évocateurs de gale et de pédiculoses","contenu":"<div class=\"notion-course\"><h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Gale</span> — forme typique</h4>\n      <p>Le maître symptôme est un <strong><span><span class=\"nc-red_bg\">prurit</span></span><span class=\"nc-red_bg\"> diffus à recrudescence nocturne</span></strong>,\n      qui <strong><span class=\"nc-green_bg\">épargne le visage</span></strong> et a souvent un <strong>caractère conjugal ou familial</strong>.\n      Penser à la <span>gale</span> devant tout <span>prurit</span> : certaines formes sont pauci-lésionnelles.</p>\n      <p><strong>Lésions non spécifiques</strong> (de grattage), de topographie évocatrice :\n      <span><span class=\"nc-blue nc-bold\">espaces interdigitaux</span></span>, <span class=\"nc-blue nc-bold\">face antérieure des poignets</span> et des avant-bras, coudes,\n      <span>aisselles</span>, région <span>ombilicale</span>, fesses et face interne\n      des cuisses ; <span>mamelon/aréole</span> chez la femme,\n      <span>OGE (verge)</span> chez l'homme.</p>\n      <p><strong>Lésions spécifiques</strong> de la <span>gale</span> :</p>\n      <table>\n        <thead><tr><th><span>Lésion</span></th><th>Topographie</th><th>Lésion élémentaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Sillon scabieux</span></strong></td><td><span class=\"nc-blue nc-bold\">Espaces interdigitaux</span> ; <span class=\"nc-blue nc-bold\">face antérieure des poignets</span></td><td><span>Lésion</span> <span>sinueuse</span> de quelques mm = <span class=\"nc-red nc-bold\">trajet de l'acarien femelle dans la couche cornée</span>, contenant <span>les</span> <span class=\"nc-blue_bg\">œufs</span> ; <span><span class=\"nc-yellow_bg\">éminence acarienne</span></span> à une extrémité (position du parasite)</td></tr>\n          <tr><td><strong><span>Vésicule</span> perlée</strong></td><td><span class=\"nc-blue nc-bold\">Espaces interdigitaux</span></td><td>Petite <span>élevure translucide</span> reposant sur une <span class=\"nc-blue nc-bold\">base érythémateuse</span></td></tr>\n          <tr><td><strong><span>Nodule</span> scabieux</strong></td><td><span class=\"nc-blue nc-bold\">Régions génitales de l'homme</span></td><td><span>Papulo-nodule</span> rouge ou violacé, prurigineux, parfois excorié</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculoses — signes évocateurs</h4>\n      <table>\n        <thead><tr><th>Pédiculose</th><th><span>Prurit</span> / lésions</th><th>Diagnostic de certitude</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cuir chevelu</strong></td><td><span><span class=\"nc-red nc-bold\">Prurit du cuir chevelu</span></span> diurne et nocturne, <span class=\"nc-blue_bg\">diffus</span> ou à <span class=\"nc-blue_bg\">prédominance </span><span><span class=\"nc-blue_bg\">rétro-auriculaire</span></span>, extension à la <span class=\"nc-blue_bg\">nuque</span> ; <span class=\"nc-red nc-bold\">lésions de grattage</span> ; <span><span class=\"nc-purple_bg\">impétiginisation</span> du <span class=\"nc-purple_bg\">cou</span></span> + <span><span class=\"nc-orange_bg\">adénopathies</span></span><span class=\"nc-orange_bg\"> occipitales</span></td><td><span><span class=\"nc-yellow_bg nc-bold\">Poux vivants</span></span> (bruns, <span class=\"nc-red nc-bold\">allongés</span>, <span class=\"nc-red nc-bold\">très mobiles</span>) ; <span>les</span> <span><span class=\"nc-yellow_bg nc-bold\">lentes</span> <span class=\"nc-yellow_bg nc-bold\">vivantes</span></span> orientent (œufs collés au cheveu, ne coulissant pas, rétro-auriculaires)</td></tr>\n          <tr><td><strong>Corporelle</strong></td><td><span><span class=\"nc-red nc-bold\">Prurit intense</span></span> ; <span class=\"nc-red nc-bold\">excoriations</span> + <span><span class=\"nc-red nc-bold\">éruption</span></span><span class=\"nc-red nc-bold\"> maculo-papuleuse</span> prédominant au <span class=\"nc-blue_bg\">dos</span>, au <span class=\"nc-blue_bg\">thorax</span> et à la <span class=\"nc-blue_bg\">racine des membres</span> ; <span><span class=\"nc-yellow_bg\">leucomélanodermie</span></span> si infestation chronique</td><td><span class=\"nc-purple nc-bold\">Poux</span> et <span class=\"nc-purple nc-bold\">lentes</span> surtout sur <span>les</span> <strong>vêtements (coutures)</strong></td></tr>\n          <tr><td><strong>Phtiriase pubienne</strong></td><td><span><span class=\"nc-red nc-bold\">Prurit pubien</span></span> + <span class=\"nc-blue_bg\">lésions de grattage</span> du pubis et de l'hypogastre</td><td><span><span class=\"nc-purple_bg\">Lentes</span></span> grisâtres et <span><span class=\"nc-purple_bg\">poux</span> <span class=\"nc-red nc-bold\">immobiles</span></span> à la base des poils</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Penser à la <strong><span>gale</span></strong> devant tout <span><span class=\"nc-red nc-bold\">prurit</span></span>.\n      Tout <strong><span>impétigo</span> de l'adulte</strong> doit faire rechercher une gale ; tout impétigo de la\n      <strong><span class=\"nc-blue_bg\">nuque</span> ou du <span class=\"nc-blue_bg\">cuir chevelu</span></strong> doit faire rechercher une <span class=\"nc-pink nc-bold\">pédiculose</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 116 — <span>Prurit</span> · 155 — Infection cutanéo-muqueuse</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":3},{"id":"171-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes atypiques de gale et de pédiculoses","contenu":"<div class=\"notion-course\"><h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Gale</span> — formes cliniques particulières</h4>\n      <table>\n        <thead><tr><th>Forme</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Gale</span> du nourrisson</strong></td><td><strong>Atteinte possible du <span class=\"nc-red nc-bold\">visage</span></strong> ; <span><span class=\"nc-blue_bg\">vésico-pustules</span> palmo-<span class=\"nc-red nc-bold\">plantaires</span></span> ; <strong><span class=\"nc-blue_bg\">nodules scabieux</span> <span class=\"nc-red nc-bold\">péri-axillaires</span></strong> (et non génitaux comme chez l'adulte)</td></tr>\n          <tr><td><strong><span>Gale</span> profuse</strong></td><td><span>Éruption</span> profuse et étendue, <strong>y compris le <span class=\"nc-blue_bg\">dos</span></strong> ; <span>terrain</span> : personne âgée alitée, troubles des fonctions supérieures<br>Causes : diagnostic tardif ; déficit immunitaire (<span><span class=\"nc-purple_bg\">VIH</span></span> ++) ; traitement inadapté (<span>corticothérapie</span>)</td></tr>\n          <tr><td><strong><span>Gale</span> hyperkératosique</strong></td><td><span>Terrain</span> : <span class=\"nc-orange_bg\">immunodéprimés</span> ou sujets âgés sous <span>immunosuppresseurs</span> (<span>corticothérapie</span>) ; <span><span class=\"nc-red nc-bold\">contagiosité majeure</span></span> (prolifération <span>parasitaire</span> intense) ; <span>prurit</span> discret voire absent ; atteinte de tout le corps y compris <span class=\"nc-blue_bg\">visage</span>, <span class=\"nc-blue_bg\">cuir chevelu</span> et <strong>ongles</strong>, voire <span>érythrodermie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes compliquées</strong> : <span>impétiginisation</span> (cause majeure de\n      <span><span class=\"nc-red\">RAA</span></span> et de <span>glomérulonéphrite post-streptococcique</span>\n      dans <span>les</span> pays en développement) ; <span class=\"nc-orange_bg\">eczématisation</span> (secondaire à la <span>gale</span> ou à son traitement).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"nc-blue_bg\">Nodules scabieux</span> <span>vs</span> post-scabieux (à distinguer)</h4>\n      <table>\n        <thead><tr><th></th><th><span class=\"nc-blue_bg\">Nodules scabieux</span></th><th><span class=\"nc-orange_bg\">Nodules post-scabieux</span></th></tr></thead>\n        <tbody>\n          <tr><td>Siège</td><td>Régions génitales</td><td>Ubiquitaire</td></tr>\n          <tr><td>Aspect</td><td>Papulo-nodules rouges/violets</td><td>Papulo-nodules rouges/cuivrés</td></tr>\n          <tr><td>Sarcopte</td><td><strong>En contiennent</strong></td><td><strong>N'en contiennent pas</strong> — réaction immuno-<span>allergique</span></td></tr>\n          <tr><td><span>Évolution</span></td><td>Régressent avec le traitement</td><td><span>Persistent plusieurs semaines après un traitement efficace</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> <span>Les</span> <strong><span class=\"nc-orange_bg\">nodules post-scabieux</span></strong>\n      qui persistent après traitement ne contiennent pas de sarcopte et <span>ne justifient pas\n      un retraitement</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculose corporelle — infections transmises par le pou de corps</h4>\n      <ul>\n        <li><strong><span><span class=\"nc-red_bg\">Fièvre</span></span><span class=\"nc-red_bg\"> récurrente cosmopolite</span></strong> — <span><span class=\"nc-purple_bg\">Borrelia recurrentis</span></span>.</li>\n        <li><strong>Typhus exanthématique (épidémique)</strong> — <span>Rickettsia prowazekii</span> (à ne pas confondre avec la <span>fièvre</span> typhoïde).</li>\n        <li><strong><span><span class=\"nc-red_bg\">Fièvre</span></span><span class=\"nc-red_bg\"> des tranchées</span></strong> — <span><span class=\"nc-purple_bg\">Bartonella quintana</span></span> : recrudescence chez <span>les</span> sujets précaires et <span><span class=\"nc-red nc-bold\">alcooliques</span></span> des métropoles ; responsable de <span><span class=\"nc-red nc-bold\">septicémie</span></span> et d'<span><span class=\"nc-red nc-bold\">endocardite</span></span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span>VIH</span> · 152 — <span>Endocardite</span> infectieuse · 261 — Néphropathie glomérulaire</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-6","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie de lésions de gale","contenu":"<div class=\"notion-course\"><p>La sémiologie de la <span>gale</span> se résume en quatre lésions, photographiées sur cette planche de référence :</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/171/gale-lesions-planche.png\" alt=\"Planche de 4 photographies de lésions de gale : sillon scabieux des espaces interdigitaux, vésicules perlées de l&#x27;avant-bras, nodules scabieux de la verge, gale hyperkératosique\" loading=\"lazy\">\n        <figcaption>Quatre lésions de gale : sillon interdigital, vésicules perlées, nodules scabieux de la verge, gale hyperkératosique. Source : fiche source EDN item 171 (Pilly / Collège de dermatologie).</figcaption>\n      </figure>\n      <table>\n        <thead><tr><th><span>Lésion</span></th><th>Code</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Sillon scabieux</span></strong></td><td>P-171-1</td><td><span>lésion</span> <span>sinueuse</span> de quelques millimètres dans un <span>espace interdigital</span> : trajet de l'acarien femelle.</td></tr>\n          <tr><td><strong><span>Vésicules perlées</span></strong></td><td>P-171-2</td><td><span class=\"nc-blue nc-bold\">petites </span><span><span class=\"nc-blue nc-bold\">élevures translucides</span></span> sur <span class=\"nc-blue nc-bold\">base érythémateuse</span>, ici à l'avant-bras.</td></tr>\n          <tr><td><strong><span class=\"nc-blue_bg\">Nodules scabieux</span></strong></td><td>P-171-3</td><td><span>papulo-nodules</span> rouges de la <span>verge</span>, de <span>diamètre</span> <span>5-10 mm</span>.</td></tr>\n          <tr><td><strong><span>Gale</span> hyperkératosique</strong></td><td>P-171-4</td><td><span>placards érythémato-squameux étendus</span> : <span class=\"nc-red nc-bold\">contagiosité majeure</span>.</td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":1},{"id":"171-7","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’une pédiculose du cuir chevelu","contenu":"<div class=\"notion-course\"><figure class=\"obj-figure\">\n        <img src=\"../assets/images/171/pediculose-cuir-chevelu-lentes.png\" alt=\"Photographie de cuir chevelu : lentes blanc-grisâtres collées à la base des cheveux au cours d&#x27;une pédiculose du cuir chevelu\" loading=\"lazy\">\n        <figcaption>Pédiculose du cuir chevelu : lentes (œufs) blanc-grisâtres collées à la t<span>ige</span> pilaire. Source : fiche source EDN item 171 (Collège de dermatologie).</figcaption>\n      </figure>\n      <ul>\n        <li><strong><span><span class=\"nc-yellow_bg nc-bold\">Lentes</span></span></strong> — œufs blanc-grisâtres <strong>collés à la t<span>ige</span> pilaire</strong>, qui <span>ne coulissent pas</span> le long du cheveu (à la différence des <span>pellicules</span>) ; <span class=\"nc-blue_bg\">prédominance </span><span><span class=\"nc-blue_bg\">rétro-auriculaire</span></span>.</li>\n        <li>Une lente située <span><span class=\"nc-pink nc-bold\">&gt; 1 cm</span></span> de l'émergence du cheveu est <strong>non viable</strong> (cheveu déjà poussé).</li>\n        <li><strong><span class=\"nc-purple nc-bold\">Poux</span></strong> adultes — bruns, <span class=\"nc-red nc-bold\">allongés</span>, mobiles ; la découverte de <span><span class=\"nc-yellow_bg nc-bold\">poux vivants</span></span> fait le <strong>diagnostic de certitude</strong>.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’association d’un bilan d’infections sexuellement transmissibles (IST) au diagnostic de gale ou pédiculose de corps ou de pubis","contenu":"<div class=\"notion-course\"><p>La <strong><span>gale du pubis</span></strong> et la <strong><span>phtiriase pubienne</span></strong> correspondent à des\n      <span>infections sexuellement transmissibles (<span class=\"nc-red nc-bold\">IST</span>)</span>.</p>\n      <p>Conduite à tenir devant l'une de ces atteintes — ou devant une <span>gale</span> survenue dans un contexte de\n      <strong>rapports sexuels à risque</strong> :</p>\n      <ul>\n        <li><strong>Rechercher <span class=\"nc-red nc-bold\">systématiquement</span> <span>les</span> autres <span>IST</span></strong> : prescrire un <span>bilan d'IST</span>.</li>\n        <li><strong>Dépister et traiter <span>les</span> <span class=\"nc-red nc-bold\">partenaires sexuels</span></strong>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Il n'existe <strong>pas de signe <span>biologique</span>\n      spécifique</strong> de la <span>gale</span> elle-même : le bilan biologique demandé est celui des\n      <strong><span><span class=\"nc-red nc-bold\">IST</span></span> associées</strong>, pas un bilan « de gale ».</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span>IST</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications du diagnostic parasitologique","contenu":"<div class=\"notion-course\"><p>Le diagnostic de <span>gale</span> est <strong>avant tout clinique</strong> (anamnèse + topographie évocatrice) ;\n      l'<span>examen parasitologique</span> n'est <strong>pas obl<span>iga</span>toire</strong> pour le poser.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen parasitologique direct — technique</h4>\n      <ul>\n        <li>Gratter un <span>sillon</span> au <strong>vaccinostyle</strong>, en prélevant si possible l'<span><span class=\"nc-yellow_bg\">éminence acarienne</span></span>.</li>\n        <li>Observation au <strong><span class=\"nc-yellow_bg\">microscope</span></strong> : met en évidence <span>les</span> <span><span class=\"nc-blue_bg\">œufs</span></span> ou l'<span>acarien femelle adulte</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications</h4>\n      <ul>\n        <li>Confirmation en cas de <strong>doute diagnostique</strong> ou de forme atypique.</li>\n        <li><strong>Négativation</strong> exigée avant de lever l'éviction des gales <span><span class=\"nc-orange_bg\">profuses</span></span><span class=\"nc-orange_bg\"> et </span><span><span class=\"nc-orange_bg\">hyperkératosiques</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Limite.</strong> La mise en évidence du parasite est\n      <span><span class=\"nc-red nc-bold\">difficile en dehors des formes profuses et hyperkératosiques</span></span> : un examen\n      négatif n'élimine pas une <span>gale</span> commune.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’intérêt du dermatoscope pour le diagnostic de gale","contenu":"<div class=\"notion-course\"><p>La <span>dermatoscopie</span> est un examen simple et non invasif, réalisable au cabinet.</p>\n      <ul>\n        <li>Elle montre un <span class=\"nc-blue_bg\">aspect caractéristique </span><strong><span class=\"nc-blue_bg\">« en</span> <span><span class=\"nc-blue_bg nc-bold\">deltaplane</span></span> »</strong> : la tête de l'acarien femelle visible à l'extrémité du <span>sillon</span>.</li>\n        <li>Elle permet de <strong>remplacer l'<span>examen parasitologique</span></strong>, peu accessible en pratique de ville.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le diagnostic de <span>gale</span> reste <strong>avant tout\n      clinique</strong> : ni la dermatoscopie ni l'<span>examen parasitologique</span> ne sont obl<span>iga</span>toires pour le poser.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement d’une gale et d’une pédiculose","contenu":"<div class=\"notion-course\"><ul><li>Gale commune : traitement topique (notamment <span class=\"nc-pink_bg\">perméthrine</span>) ou <span class=\"nc-pink_bg\">ivermectine</span> orale selon terrain, faisabilité et recommandations. Répéter le traitement au délai indiqué, généralement entre J7 et J14, en respectant le RCP du produit.</li><li><span class=\"nc-pink nc-bold\">L’ivermectine</span> n’est pas automatiquement supérieure ni première intention universelle. Enfant de moins de 15 kg, grossesse et allaitement : recommandations SFD spécifiques, avec possibilité d’usage hors AMM dans certaines situations encadrées ; pas de contre-indication uniforme à tous les traitements.</li><li>Appliquer les topiques soigneusement sur toutes les zones requises selon âge/forme, durée de pose et réapplication après lavage des mains. Traiter simultanément les contacts indiqués et gérer vêtements/literie.</li><li>Gale hyperkératosique : avis spécialisé, traitements associés et répétés, précautions <span class=\"nc-green_bg nc-bold\">contact</span> et gestion élargie des contacts/environnement.</li><li><span class=\"nc-purple nc-bold\">Poux</span> de tête : traiter une infestation active, privilégier un produit à action physique adapté (<span class=\"nc-pink nc-bold\">diméticone</span>), peigne et répétition selon notice. Examiner l’entourage ; ne pas traiter préventivement tous les enfants sans infestation. Pou de corps : hygiène, vêtements propres et décontamination ; phtiriase : partenaires et bilan d’IST.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":2},{"id":"171-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de traitement des sujets contacts en cas de diagnostic de gale","contenu":"<div class=\"notion-course\"><p>Le traitement des contacts est <strong>simultané</strong> à celui du cas index.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Qui traiter</h4>\n      <ul>\n        <li><span>Les</span> <strong><span>contacts proches</span></strong> : personnes <strong>vivant sous le même toit</strong> et <strong><span class=\"nc-red nc-bold\">partenaires sexuels</span></strong>.</li>\n        <li><strong>Même s'ils sont asymptomatiques.</strong></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Comment</h4>\n      <ul>\n        <li><strong>Même traitement</strong> que le cas index : soit un <span>traitement local</span> (peut suffire), soit <span class=\"nc-pink nc-bold\">l'</span><span><span class=\"nc-pink nc-bold\">ivermectine</span></span> PO — à privilégier pour l'observance quand le nombre de personnes à traiter est important.</li>\n        <li>Traiter <strong>en même temps</strong> le linge et l'environnement.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Ne pas attendre que <span>les</span> contacts\n      deviennent symptomatiques : le traitement est <strong>simultané et systématique</strong>, sinon\n      <span class=\"nc-red nc-bold\">recontamination</span> du cas index.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span>IST</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0},{"id":"171-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les causes d’échec du traitement de la gale et des pédiculoses","contenu":"<div class=\"notion-course\"><h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Gale</span> — <span>prurit</span> persistant <span>8-15 jours</span> après le traitement</h4>\n      <p>Un <span>prurit</span> qui persiste n'est pas toujours un échec. Évoquer :</p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">Eczéma de contact</span></span> ; <span><span class=\"nc-red nc-bold\">irritation par le traitement</span></span>.</li>\n        <li><span><span class=\"nc-red nc-bold\">Parasitophobie</span></span> ; autres causes de <span>prurit</span>.</li>\n        <li><strong><span class=\"nc-orange_bg\">Nodules post-scabieux</span></strong> persistants — réaction immuno-<span>allergique</span>, qui <span>ne justifient pas un retraitement</span>.</li>\n      </ul>\n      <p><strong>Échec vrai</strong> (lésions cliniques évocatrices et/ou <span>examen parasitologique</span> positif) :\n      <span><span class=\"nc-red nc-bold\">rechute</span></span> après un traitement inapproprié ; <span class=\"nc-red nc-bold\">rechute</span> liée à une\n      <span><span class=\"nc-red nc-bold\">résistance</span></span> au traitement ; <span><span class=\"nc-red nc-bold\">recontamination</span></span>\n      après guérison.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculoses — causes d'échec</h4>\n      <ul>\n        <li>Incompréhension, ignorance, négligence ; <span>coût</span> (aucune spécialité n'est remboursée).</li>\n        <li><span>Réinfestation</span> à partir de l'environnement.</li>\n        <li>Durée ou fréquence d'utilisation insuffisantes ; <span>quantité de produit insuffisante</span> ; forme galénique inappropriée.</li>\n        <li><span><span class=\"nc-orange_bg\">Acquisition de résistance</span></span><span class=\"nc-orange_bg\"> des poux</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"nc-pink nc-bold\">Pédiculose</span> du <span class=\"nc-blue_bg\">cuir chevelu</span> — examen de contrôle.</strong> <span class=\"nc-yellow_bg nc-bold\">Poux vivants</span>\n      à <span>J2</span> → <span><span class=\"nc-red nc-bold\">résistance</span></span> probable → <strong>changer de\n      classe</strong> pharmacologique. <span class=\"nc-yellow_bg nc-bold\">Poux vivants</span> à <span>J12</span> → <span class=\"nc-red nc-bold\">mauvais effet lenticide</span>\n      → <strong>refaire le produit initial</strong>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":1},{"id":"171-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de gestion d’une épidémie de gale dans un établissement","contenu":"<div class=\"notion-course\"><ul><li>Confirmer le cas et prévenir l’équipe d’hygiène ; définir exposition, période et type de gale. Les formes <span class=\"nc-red nc-bold\">hyperkératosiques</span> imposent une enquête et un périmètre plus larges.</li><li>Traitement coordonné des cas et contacts selon cercles d’exposition, y compris contacts asymptomatiques indiqués. Traiter tous les visiteurs sans évaluation n’est pas une règle universelle.</li><li>Précautions <span class=\"nc-green_bg nc-bold\">contact</span>, information, linge traité par lavage adapté ou isolement en sac selon recommandations et type de gale. La durée de survie varie avec température/humidité ; 12–24 heures ne constitue pas une garantie.</li><li>Planifier la deuxième prise/application et la surveillance des nouveaux cas. Éviction et levée d’isolement dépendent de la forme et du protocole ; pour une gale hyperkératosique, avis spécialisé et contrôle parasitologique.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 171</a></li><li><a href=\"https://centredepreuves.sfdermato.org/recommandation-cdp/48-gale-de-lenfant-et-femme-enceinteallaitante\" target=\"_blank\" rel=\"noopener noreferrer\">SFD · gale chez l’enfant de moins de 15 kg et pendant grossesse/allaitement, 2024</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-def\">Isolement</span> immédiat :</strong> toute <span class=\"kw-etio\">gale</span> <span class=\"kw-alerte\">profuse</span> ou <span class=\"kw-alerte\">hyperkératosique</span> (contagiosité majeure) impose un <span class=\"kw-ttt\">isolement</span> avec <span class=\"kw-def\">précautions complémentaires de type contact</span>, idéalement en <span class=\"kw-alerte\">hospitalisation</span>.</p><p><strong>Répétition obl<span class=\"kw-chiffre\">iga</span>toire :</strong> <span class=\"kw-ttt\">ivermectine</span> à répéter à <span class=\"kw-chiffre\">7-14 jours</span> (cycle <span class=\"kw-etio\">parasitaire</span>) ; traitement local renouvelé à <span class=\"kw-chiffre\">7-8 jours</span> ; pédiculose retraitée à <span class=\"kw-chiffre\">7-10 jours</span> (mauvais effet lenticide) — sans cette 2ᵉ prise, l’échec est quasi assuré.</p><p><strong><span class=\"kw-etio\">Décontamination</span> du linge :</strong> lavage <span class=\"kw-chiffre\">&gt; 60 °C</span> en machine (cycle long) ou linge enfermé en sac plastique <span class=\"kw-chiffre\">72 h</span> (gale) / <span class=\"kw-chiffre\">7 jours</span> (pou de corps).</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-etio\">gale</span> commune et pédiculoses se traitent en <span class=\"kw-ttt\">ambulatoire</span> (traitement local ou <span class=\"kw-ttt\">ivermectine</span> per os).</p><p><strong><span class=\"kw-alerte\">Hospitalisation</span> / <span class=\"kw-def\">isolement</span> :</strong> gale <span class=\"kw-alerte\">profuse</span> ou <span class=\"kw-alerte\">hyperkératosique</span> — isoler le malade, <span class=\"kw-def\">précautions complémentaires de type contact</span>, idéalement en hospitalisation.</p><p><strong>Épidémie en collectivité (<span class=\"kw-def\">EHPAD</span> ++) :</strong> traiter TOUS <span class=\"kw-clinique\">les</span> membres en même temps (soignants, patients, visiteurs) même asymptomatiques, par <span class=\"kw-ttt\">ivermectine</span> per os, + traitement de l’environnement.</p><p><strong>Orientation <span class=\"kw-clinique\">IST</span> :</strong> gale du <span class=\"kw-etio\">pubis</span>, <span class=\"kw-etio\">phtiriase pubienne</span> ou gale après rapport à risque → <span class=\"kw-bio\">bilan d’IST</span> et <span class=\"kw-def\">dépistage</span>/traitement des partenaires.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Gale hyperkératosique</span> : contagiosité majeure par prolifération <span class=\"kw-etio\">parasitaire</span> intense → <span class=\"kw-def\">isolement</span> ; possible <span class=\"kw-alerte\">érythrodermie</span>, atteinte des <span class=\"kw-clinique\">ongles</span>, du visage et du cuir chevelu</li><li><span class=\"kw-alerte\">Gale profuse</span> : <span class=\"kw-clinique\">éruption</span> étendue y compris le <span class=\"kw-clinique\">dos</span> ; <span class=\"kw-def\">terrain</span> immunodéprimé (<span class=\"kw-etio\">VIH</span>), personne âgée alitée, diagnostic tardif ou <span class=\"kw-etio\">corticothérapie</span></li><li><span class=\"kw-alerte\">Surinfection / impétiginisation</span> des lésions de grattage — tout <span class=\"kw-clinique\">impétigo de l’adulte</span> doit faire rechercher une <span class=\"kw-etio\">gale</span> ; cause majeure de <span class=\"kw-alerte\">RAA</span> et de <span class=\"kw-alerte\">glomérulonéphrite post-streptococcique</span> dans <span class=\"kw-clinique\">les</span> pays en développement</li><li><span class=\"kw-alerte\">Pédiculose corporelle</span> : le pou de corps transmet la <span class=\"kw-etio\">fièvre des tranchées</span> (<span class=\"kw-etio\">Bartonella quintana</span>) responsable de <span class=\"kw-alerte\">septicémie</span> et d’<span class=\"kw-alerte\">endocardite</span>, le <span class=\"kw-etio\">typhus exanthématique</span> et la <span class=\"kw-etio\">fièvre récurrente cosmopolite</span></li><li><span class=\"kw-clinique\">Prurit</span> persistant <span class=\"kw-chiffre\">8-15 jours</span> après traitement, avec lésions évocatrices et/ou <span class=\"kw-bio\">examen parasitologique</span> positif = <span class=\"kw-alerte\">échec vrai</span> (rechute, résistance ou recontamination)</li></ul>","principes":"<p><span class=\"kw-etio\">Gale</span> : <span class=\"kw-ttt\">ivermectine</span> per os en 1ʳᵉ intention, traitements locaux en alternative ou en association ; traitement <strong>simultané des contacts</strong> et de l’environnement. Pédiculoses : traitement <span class=\"kw-ttt\">local</span> par <span class=\"kw-ttt\">diméticone</span>, 2ᵉ application systématique.</p><p><strong><span class=\"kw-etio\">Gale</span> — traitement général (1ʳᵉ intention)</strong></p><ul><li><span class=\"kw-ttt\">Ivermectine</span> per os en <strong>prise unique</strong>, AMM chez l’adulte et l’enfant <span class=\"kw-chiffre\">&gt; 2 ans et &gt; 15 kg</span> — <span class=\"kw-ci\">CI &lt; 2 ans ou &lt; 15 kg</span></li><li>À <strong>répéter systématiquement à <span class=\"kw-chiffre\">7-14 jours</span></strong> (cycle <span class=\"kw-etio\">parasitaire</span> ; hors AMM mais indispensable pour éviter <span class=\"kw-clinique\">les</span> échecs)</li></ul><p><strong><span class=\"kw-etio\">Gale</span> — traitements locaux</strong></p><ul><li><span class=\"kw-ttt\">Benzoate de benzyle</span> émulsion <span class=\"kw-chiffre\">10 %</span> : du <strong>cuir chevelu aux orteils</strong>, dès <span class=\"kw-chiffre\">1 mois</span> — <span class=\"kw-ci\">CI &lt; 1 mois (toxicité neurologique)</span> ; pose <span class=\"kw-chiffre\">24 h</span> chez l’adulte, <span class=\"kw-chiffre\">6-12 h</span> entre <span class=\"kw-chiffre\">1 mois</span> et <span class=\"kw-chiffre\">2 ans</span> ; 2 applications à <span class=\"kw-chiffre\">8 jours</span></li><li><span class=\"kw-ttt\">Perméthrine</span> crème <span class=\"kw-chiffre\">5 %</span> : du <strong>cou aux orteils</strong>, dès <span class=\"kw-chiffre\">2 mois</span> ; pose <span class=\"kw-chiffre\">8-12 h</span> ; 2 applications à <span class=\"kw-chiffre\">7 jours</span></li><li><span class=\"kw-clinique\">Les</span> deux sont <strong>possibles chez la femme enceinte</strong>, <span class=\"kw-ci\">hors allaitement</span></li></ul><p><strong><span class=\"kw-etio\">Gale</span> — modalités d’application locale</strong></p><ul><li>Après une <span class=\"kw-ttt\">douche tiède au savon</span>, appliquer sur <strong>tout le corps</strong> zones génitales comprises (+ cuir chevelu et visage en cas de doute)</li><li><span class=\"kw-ci\">Ne pas se laver</span> pendant la durée de pose ; au retrait, douche puis <span class=\"kw-ttt\">émollient</span> (peau sèche et prurigineuse)</li></ul><p><strong><span class=\"kw-etio\">Gale</span> profuse / hyperkératosique</strong></p><ul><li><strong>Associer systématiquement</strong> le traitement <span class=\"kw-ttt\">local</span> + l’<span class=\"kw-ttt\">ivermectine</span> per os</li><li><span class=\"kw-ttt\">Isolement</span> du malade (<span class=\"kw-def\">précautions de type contact</span>), idéalement en <span class=\"kw-alerte\">hospitalisation</span> ; désinfection des lieux de vie</li></ul><p><strong>Sujets contacts (<span class=\"kw-etio\">gale</span>)</strong></p><ul><li>Traiter <strong>simultanément</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">contacts proches</span> : personnes vivant <strong>sous le même toit</strong> et <strong>partenaires sexuels</strong>, <strong>même asymptomatiques</strong></li><li>Même traitement que le cas index : <span class=\"kw-ttt\">traitement local</span> ou <span class=\"kw-ttt\">ivermectine</span> per os (à privilégier si le nombre de personnes est important, pour l’observance)</li></ul><p><strong>Environnement (<span class=\"kw-etio\">gale</span>)</strong></p><ul><li>Linge, draps et serviettes lavés à <span class=\"kw-chiffre\">&gt; 60 °C</span> en machine (cycle long) <strong>ou</strong> enfermés en sac plastique <span class=\"kw-chiffre\">72 h</span></li><li>Désinfection des lieux de vie uniquement si <span class=\"kw-etio\">gale</span> <span class=\"kw-alerte\">profuse</span> (inutile si gale commune)</li></ul><p><strong>Pédiculoses — principe général</strong></p><ul><li>Traitement <span class=\"kw-ttt\">local</span> par <span class=\"kw-ttt\">diméticone</span> ou <span class=\"kw-ttt\">oxyphtirine</span> (destruction <strong>mécanique</strong> du pou ; malathion et perméthrine ne sont plus disponibles)</li><li><strong>2ᵉ traitement systématique à <span class=\"kw-chiffre\">7-10 jours</span></strong> (mauvais effet lenticide) ; solutions, lotions et crèmes préférées aux <span class=\"kw-ci\">shampooings et poudres</span> (moins efficaces)</li><li><span class=\"kw-ci\">Pas de traitement présomptif</span> : seules <span class=\"kw-clinique\">les</span> pédiculoses actives se traitent</li></ul><p><strong>Pédiculose du cuir chevelu</strong></p><ul><li><span class=\"kw-ttt\">Diméticone</span> en solution/lotion appliquée <strong>raie par raie</strong>, pose <span class=\"kw-chiffre\">15 min à 1 h</span>, puis shampooing doux + rinçage + <strong>peignage</strong> ; refait à <span class=\"kw-chiffre\">7-10 jours</span></li><li>Échec d’un traitement local bien conduit : <span class=\"kw-ttt\">ivermectine</span> per os <span class=\"kw-chiffre\">400 µg/kg</span> en prise unique (<span class=\"kw-alerte\">hors AMM</span> ; &gt;<span class=\"kw-chiffre\"> 2 ans</span> et &gt;<span class=\"kw-chiffre\"> 15 kg</span> ; répétée à <span class=\"kw-chiffre\">7 jours</span>)</li><li>Désinfection des locaux <span class=\"kw-ci\">inutile</span> ; linge à <span class=\"kw-chiffre\">≥ 50 °C</span> ou aérosol insecticide ; traitement de la fratrie non indispensable, éviction scolaire <span class=\"kw-ci\">non systématique</span></li></ul><p><strong>Pédiculose corporelle</strong></p><ul><li><span class=\"kw-ttt\">Hygiène corporelle</span>, douche au savon, <strong>changement de vêtements</strong></li><li>Linge et literie lavés à <span class=\"kw-chiffre\">60 °C</span> en machine (cycle long) ou enfermés en sac plastique <span class=\"kw-chiffre\">7 jours</span></li></ul><p><strong>Phtiriase pubienne (<span class=\"kw-clinique\">IST</span>)</strong></p><ul><li><strong>Rechercher systématiquement <span class=\"kw-clinique\">les</span> autres <span class=\"kw-bio\">IST</span></strong> + dépister et traiter les partenaires sexuels</li><li><span class=\"kw-ttt\">Perméthrine</span> topique réitérée à <span class=\"kw-chiffre\">7 jours</span> ; le <span class=\"kw-ttt\">rasage</span> est le meilleur traitement</li></ul>","suivi":"<p><strong><span class=\"kw-etio\">Gale</span> — <span class=\"kw-clinique\">prurit</span> persistant <span class=\"kw-chiffre\">8-15 jours</span> (pas toujours un échec)</strong></p><ul><li>Évoquer : <span class=\"kw-etio\">eczéma de contact</span>, <span class=\"kw-etio\">irritation par le traitement</span>, <span class=\"kw-etio\">parasitophobie</span>, autres causes de <span class=\"kw-clinique\">prurit</span></li><li><strong>Nodules post-scabieux</strong> : réaction immuno-<span class=\"kw-etio\">allergique</span> sans sarcopte, persistent plusieurs semaines — <span class=\"kw-ci\">ne justifient pas un retraitement</span></li></ul><p><strong><span class=\"kw-etio\">Gale</span> — échec vrai</strong></p><ul><li>Lésions cliniques évocatrices et/ou <span class=\"kw-bio\">examen parasitologique</span> positif</li><li>Causes : <span class=\"kw-etio\">rechute</span> après traitement inapproprié, <span class=\"kw-alerte\">résistance</span> au traitement, <span class=\"kw-etio\">recontamination</span> après guérison</li></ul><p><strong>Pédiculose du cuir chevelu — examen de contrôle</strong></p><ul><li>Poux vivants à <span class=\"kw-chiffre\">J2</span> → <span class=\"kw-alerte\">résistance</span> probable → <strong>changer de classe pharmacologique</strong></li><li>Poux vivants à <span class=\"kw-chiffre\">J12</span> → mauvais effet lenticide → <strong>refaire le produit initial</strong></li></ul><p><strong>Pédiculoses — causes d’échec</strong></p><ul><li>Incompréhension, négligence, <span class=\"kw-etio\">coût</span> (aucune spécialité remboursée) ; <span class=\"kw-etio\">réinfestation</span> à partir de l’environnement</li><li>Durée/fréquence insuffisantes, <span class=\"kw-etio\">quantité de produit insuffisante</span>, forme galénique inappropriée, <span class=\"kw-alerte\">acquisition de résistance</span> des poux</li></ul><p><strong>Éviction de la collectivité</strong></p><ul><li><span class=\"kw-etio\">Gale</span> commune : jusqu’à <span class=\"kw-chiffre\">3 jours</span> après le début du traitement</li><li><span class=\"kw-etio\">Gale</span> profuse / hyperkératosique : jusqu’à <strong>négativation de l’<span class=\"kw-bio\">examen parasitologique</span></strong></li><li>Pédiculose du cuir chevelu : éviction scolaire <span class=\"kw-ci\">non systématique</span> ; prévenir <span class=\"kw-clinique\">les</span> parents par écrit + examen de groupe</li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-171.pdf","label":"Collège Pilly — Voyageur (item 171, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Ectoparasitose confirmée — Diagnostic clinique : gale (Sarcoptes scabiei) ou pédiculose (poux)","detail":"<h4>CAT — Traitement de la <span class=\"kw-etio\">gale</span> et des pédiculoses — Choix thérapeutique selon l’entité, la forme, le <span class=\"kw-def\">terrain</span> et le contexte</h4>","branches":[{"to":"q-gale","label":"Gale","color":"blue"},{"to":"q-pedic","label":"Pédiculose","color":"blue"}]},{"id":"q-gale","kind":"decision","label":"Forme et contexte de la gale ? — Commune (cas isolé) · profuse/hyperkératosique · épidémie en collectivité","branches":[{"to":"t-gale-profuse","label":"Profuse / hyperkératosique","color":"red"},{"to":"t-gale-collectivite","label":"Épidémie en collectivité (EHPAD)","color":"amber"},{"to":"q-gale-terrain","label":"Gale commune, cas isolé / familial","color":"green"}]},{"id":"t-gale-profuse","kind":"terminal","label":"Gale profuse ou hyperkératosique","color":"red","detail":"<h4>Traitement</h4><ul><li>Associer <strong>systématiquement</strong> le traitement <span class=\"kw-ttt\">local</span> (benzoate de benzyle ou perméthrine) + l’<span class=\"kw-ttt\">ivermectine</span> per os</li></ul><h4><span class=\"kw-def\">Isolement</span></h4><ul><li><span class=\"kw-ttt\">Isoler</span> le malade — <span class=\"kw-def\">précautions complémentaires de type contact</span>, idéalement en <span class=\"kw-alerte\">hospitalisation</span> (contagiosité majeure)</li></ul><h4>Environnement</h4><ul><li>Linge à <span class=\"kw-chiffre\">&gt; 60 °C</span> ou sac plastique <span class=\"kw-chiffre\">72 h</span> ; <strong>désinfection des lieux de vie</strong> (indiquée seulement dans <span class=\"kw-clinique\">les</span> formes profuses)</li></ul><h4>Éviction</h4><ul><li>Enfant : jusqu’à <strong>négativation de l’<span class=\"kw-bio\">examen parasitologique</span></strong></li></ul><h4>Conduite</h4><ul><li>Traiter simultanément <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">contacts proches</span></li><li>Rechercher une cause favorisante : <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">corticothérapie</span>, diagnostic tardif</li></ul>"},{"id":"t-gale-collectivite","kind":"terminal","label":"Épidémie de gale en collectivité","color":"amber","detail":"<h4>Conduite</h4><ul><li>Traiter <strong>TOUS <span class=\"kw-clinique\">les</span> membres de la collectivité en même temps</strong> — soignants, autres patients, visiteurs — <strong>même sans signe clinique</strong></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ivermectine</span> per os (facilite l’observance d’un traitement de <span class=\"kw-clinique\">masse</span>)</li></ul><h4>Environnement</h4><ul><li>Traiter conjointement l’environnement (linge <span class=\"kw-chiffre\">&gt; 60 °C</span> ou sac <span class=\"kw-chiffre\">72 h</span>) ; en <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-def\">précautions de type contact</span></li></ul><h4>Éviction</h4><ul><li><span class=\"kw-etio\">Gale</span> commune : <span class=\"kw-chiffre\">3 jours</span> après le début du traitement</li><li>Forme profuse / hyperkératosique : jusqu’à négativation de l’<span class=\"kw-bio\">examen parasitologique</span></li></ul>"},{"id":"q-gale-terrain","kind":"decision","label":"Terrain du patient ? — Conditionne le choix ivermectine PO vs traitement local","branches":[{"to":"t-gale-iverm","label":"Adulte ou enfant > 2 ans et > 15 kg","color":"green"},{"to":"t-gale-nourrisson","label":"Nourrisson / < 2 ans ou < 15 kg","color":"amber"},{"to":"t-gale-grossesse","label":"Femme enceinte","color":"amber"}]},{"id":"t-gale-iverm","kind":"terminal","label":"Ivermectine per os (1ʳᵉ intention)","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ivermectine</span> per os en <strong>prise unique</strong>, <strong>répétée à <span class=\"kw-chiffre\">7-14 jours</span></strong> (cycle <span class=\"kw-etio\">parasitaire</span>)</li></ul><h4>Alternative</h4><ul><li>Traitement local : <span class=\"kw-ttt\">benzoate de benzyle</span> ou <span class=\"kw-ttt\">perméthrine</span></li></ul><h4>Contacts</h4><ul><li>Traiter <strong>simultanément</strong> <span class=\"kw-clinique\">les</span> contacts proches (<strong>même toit</strong> + partenaires sexuels), <strong>même asymptomatiques</strong></li></ul><h4>Environnement</h4><ul><li>Linge à <span class=\"kw-chiffre\">&gt; 60 °C</span> (cycle long) ou sac plastique <span class=\"kw-chiffre\">72 h</span></li></ul><h4>Éviction</h4><ul><li>Enfant : <span class=\"kw-chiffre\">3 jours</span> après le début du traitement</li></ul>"},{"id":"t-gale-nourrisson","kind":"terminal","label":"Traitement local (ivermectine CI)","color":"amber","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-ci\">Ivermectine contre-indiquée &lt; 2 ans ou &lt; 15 kg</span> → traitement <strong>local</strong></li></ul><h4>Molécules</h4><ul><li><span class=\"kw-ttt\">Perméthrine</span> crème <span class=\"kw-chiffre\">5 %</span> dès <span class=\"kw-chiffre\">2 mois</span>, pose <span class=\"kw-chiffre\">8-12 h</span></li><li><span class=\"kw-ttt\">Benzoate de benzyle</span> dès <span class=\"kw-chiffre\">1 mois</span> (<span class=\"kw-ci\">CI &lt; 1 mois : toxicité neurologique</span>), pose réduite <span class=\"kw-chiffre\">6-12 h</span> entre <span class=\"kw-chiffre\">1 mois</span> et <span class=\"kw-chiffre\">2 ans</span></li></ul><h4>Traitement</h4><ul><li>2 applications espacées (<span class=\"kw-chiffre\">7 jours</span> perméthrine, <span class=\"kw-chiffre\">8 jours</span> benzoate)</li></ul><h4>Conduite</h4><ul><li>Traiter aussi <span class=\"kw-clinique\">les</span> contacts et l’environnement (linge <span class=\"kw-chiffre\">&gt; 60 °C</span> ou sac <span class=\"kw-chiffre\">72 h</span>)</li></ul>"},{"id":"t-gale-grossesse","kind":"terminal","label":"Femme enceinte — traitement local","color":"amber","detail":"<h4>Traitement</h4><ul><li>Traitement <strong>local possible</strong> : <span class=\"kw-ttt\">perméthrine</span> ou <span class=\"kw-ttt\">benzoate de benzyle</span>, <span class=\"kw-ci\">hors allaitement</span></li></ul><h4>Conduite</h4><ul><li>Traiter simultanément <span class=\"kw-clinique\">les</span> contacts proches et le linge / l’environnement</li></ul>"},{"id":"q-pedic","kind":"decision","label":"Localisation de la pédiculose ? — Cuir chevelu · corporelle · pubienne","branches":[{"to":"q-pedic-cuir","label":"Cuir chevelu","color":"green"},{"to":"t-pedic-corp","label":"Corporelle","color":"green"},{"to":"t-pedic-pubis","label":"Pubienne (phtiriase)","color":"amber"}]},{"id":"q-pedic-cuir","kind":"decision","label":"Diméticone, puis examen de contrôle — Évaluation des poux vivants à J2 et J12","branches":[{"to":"t-pedic-cuir-ok","label":"Traitement initial / contrôle négatif","color":"green"},{"to":"t-pedic-j2","label":"Poux vivants à J2","color":"amber"},{"to":"t-pedic-j12","label":"Poux vivants à J12","color":"amber"},{"to":"t-pedic-iverm","label":"Échec malgré traitement local bien conduit","color":"amber"}]},{"id":"t-pedic-cuir-ok","kind":"terminal","label":"Diméticone locale","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Diméticone</span> (ou oxyphtirine) en solution/lotion, appliquée <strong>raie par raie</strong>, pose <span class=\"kw-chiffre\">15 min à 1 h</span>, puis shampooing doux + rinçage + <strong>peignage</strong></li></ul><h4>Délai</h4><ul><li><strong>2ᵉ application systématique à <span class=\"kw-chiffre\">7-10 jours</span></strong> (mauvais effet lenticide)</li></ul><h4>Environnement</h4><ul><li>Désinfection des locaux <span class=\"kw-ci\">inutile</span> ; linge à <span class=\"kw-chiffre\">≥ 50 °C</span> ou aérosol insecticide</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ci\">Pas de traitement présomptif</span> : seules <span class=\"kw-clinique\">les</span> pédiculoses actives se traitent</li><li>Traitement de la fratrie non indispensable ; éviction scolaire <span class=\"kw-ci\">non systématique</span> ; prévenir <span class=\"kw-clinique\">les</span> parents par écrit + examen de groupe</li></ul>"},{"id":"t-pedic-j2","kind":"terminal","label":"Résistance probable","color":"amber","detail":"<h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Poux vivants à <span class=\"kw-chiffre\">J2</span> = <span class=\"kw-alerte\">résistance</span> probable des poux aux insecticides</li></ul><h4>Conduite</h4><ul><li><strong>Changer de classe pharmacologique</strong></li></ul>"},{"id":"t-pedic-j12","kind":"terminal","label":"Mauvais effet lenticide","color":"amber","detail":"<h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Poux vivants à <span class=\"kw-chiffre\">J12</span> = <strong>mauvais effet lenticide</strong> (éclosion d’œufs résiduels)</li></ul><h4>Conduite</h4><ul><li><strong>Refaire le produit initial</strong></li></ul>"},{"id":"t-pedic-iverm","kind":"terminal","label":"Ivermectine per os (hors AMM)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ivermectine</span> per os <span class=\"kw-chiffre\">400 µg/kg</span> en prise unique, <strong>répétée à <span class=\"kw-chiffre\">7 jours</span></strong></li></ul><h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Sujets <span class=\"kw-chiffre\">&gt; 2 ans et &gt; 15 kg</span> ; <span class=\"kw-alerte\">hors AMM</span> dans cette indication — réservée au cuir chevelu (à ne pas utiliser dans <span class=\"kw-clinique\">les</span> autres pédiculoses)</li></ul>"},{"id":"t-pedic-corp","kind":"terminal","label":"Pédiculose corporelle","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Hygiène corporelle</span>, douche au savon, <strong>changement de vêtements</strong></li></ul><h4>Environnement</h4><ul><li>Linge et literie lavés à <span class=\"kw-chiffre\">60 °C</span> (cycle long) ou enfermés en sac plastique <span class=\"kw-chiffre\">7 jours</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-etio\">Marqueur de précarité</span> ; le pou de corps est vecteur (<span class=\"kw-etio\">fièvre des tranchées</span>, <span class=\"kw-etio\">typhus</span>, <span class=\"kw-etio\">fièvre récurrente</span>) → évoquer ces infections selon le contexte</li></ul>"},{"id":"t-pedic-pubis","kind":"terminal","label":"Phtiriase pubienne (IST)","color":"amber","detail":"<h4>Conduite</h4><ul><li><strong>Phtiriase pubienne = <span class=\"kw-bio\">IST</span></strong> : rechercher systématiquement <span class=\"kw-clinique\">les</span> autres <span class=\"kw-clinique\">IST</span> + dépister et traiter les partenaires sexuels</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Perméthrine</span> topique suivie d’un savonnage, réitérée à <span class=\"kw-chiffre\">7 jours</span> ; le <span class=\"kw-ttt\">rasage</span> est le meilleur traitement</li></ul>"}]},"cards":[{"i":"1fcd3a9752d9","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quel est le traitement de première intention pour une pédiculose du cuir chevelu ?","a":"<div class=\"notion-course\"><ul><li>Infestation active : produit à action physique adapté, notamment <span class=\"nc-pink nc-bold\">diméticone</span>, appliqué soigneusement puis peignage ; durée de pose et répétition selon la notice. Examiner <span class=\"nc-red_bg nc-bold\">l’entourage</span>, sans traitement préventif systématique des sujets non infestés.</li></ul></div>"},{"i":"677f3b07007e","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quelle est la prise en charge d'une gale profuse ou hyperkératosique ?","a":"<div class=\"notion-course\"><ul><li>Gale hyperkératosique : avis spécialisé, traitements associés et répétés, précautions <span class=\"nc-green_bg nc-bold\">contact</span> et gestion élargie des contacts/environnement.</li></ul></div>"},{"i":"88c3b90e1a52","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quels sont les traitements locaux de la gale, leurs galéniques, les âges minimaux et les zones d'application spécifiques ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink_bg\">Perméthrine</span> 5 % en crème (à partir de deux mois selon RCP) ou <span class=\"nc-pink_bg\">benzoate de benzyle</span> 10 % en émulsion (à partir d’un mois selon RCP). Respecter durée de pose et répétition propres au produit.</li><li>La surface à traiter dépend de l’âge et de la forme : ne pas exclure systématiquement tête et cuir chevelu chez le nourrisson, le sujet âgé ou en cas de lésions. Avis spécialisé pour les situations particulières.</li></ul></div>"},{"i":"9143fd3a2266","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Comment utiliser l’ivermectine orale contre la gale et quelles précautions pédiatriques respecter ?","a":"<div class=\"notion-course\"><ul><li>Option systémique à dose pondérale, généralement 200 µg/kg, répétée selon protocole à J7–J14. Le choix oral ou topique dépend du terrain et de la faisabilité.</li><li>En dessous de 15 kg : usage hors AMM éventuellement encadré par les recommandations SFD ; ce n’est ni une prescription automatique ni une interdiction fondée sur le seul âge de deux ans.</li></ul></div>"},{"i":"c7e30f61ac39","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Quelles sont les modalités d'application des traitements locaux de la gale et les mesures environnementales associées ?","a":"<div class=\"notion-course\"><ul><li>Gale commune : traitement topique (notamment <span class=\"nc-pink_bg\">perméthrine</span>) ou <span class=\"nc-pink_bg\">ivermectine</span> orale selon terrain, faisabilité et recommandations. Répéter le traitement au délai indiqué, généralement entre J7 et J14, en respectant le RCP du produit.</li><li>Appliquer les topiques soigneusement sur toutes les zones requises selon âge/forme, durée de pose et réapplication après lavage des mains. Traiter simultanément les contacts indiqués et gérer vêtements/literie.</li></ul></div>"},{"i":"e49b6c0eff0a","n":171,"o":"171-11","u":"Prise en charge","t":"Connaître le traitement d’une gale et d’une pédiculose","q":"Comment traiter une pédiculose corporelle et une phtiriase pubienne ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-purple nc-bold\">Poux</span> de corps : hygiène corporelle, changement et décontamination des vêtements/literie. Phtiriase : traitement antiparasitaire adapté, traitement des partenaires et recherche d’autres <span class=\"nc-red nc-bold\">IST</span>.</li><li>Le rasage seul ne remplace pas le traitement ; respecter les précautions spécifiques si cils atteints.</li></ul></div>"},{"i":"519c4edd542a","n":171,"o":"171-12","u":"Prise en charge","t":"Connaître les modalités de traitement des sujets contacts en cas de diagnostic de gale","q":"Quelle est la temporalité de traitement des sujets contacts en cas de gale, notamment par rapport au cas index ?","a":"<div class=\"notion-course\"><p>Le traitement des sujets contacts doit être réalisé de manière <strong>simultanée</strong> à celui du cas index. Il ne faut pas attendre l'apparition de symptômes chez les contacts pour initier le traitement.</p></div>"},{"i":"615731a1febe","n":171,"o":"171-12","u":"Prise en charge","t":"Connaître les modalités de traitement des sujets contacts en cas de diagnostic de gale","q":"Quelles sont les modalités de traitement des sujets contacts en cas de gale, et que faut-il également traiter en parallèle ?","a":"<div class=\"notion-course\"><p>Les sujets contacts reçoivent le <strong>même traitement que le cas index</strong> :</p><ul><li>Un <strong>traitement local</strong> (peut suffire).</li><li>L'<strong><span class=\"nc-pink nc-bold\">ivermectine per os</span></strong>, à privilégier pour l'observance lorsque le nombre de personnes à traiter est important.</li></ul><p>Il est indispensable de traiter également le <strong>linge</strong> et l'<strong>environnement</strong> de manière simultanée.</p></div>"},{"i":"99a9d267a936","n":171,"o":"171-12","u":"Prise en charge","t":"Connaître les modalités de traitement des sujets contacts en cas de diagnostic de gale","q":"En cas de diagnostic de gale chez un patient, qui doit être considéré comme contact et recevoir un traitement préventif ?","a":"<div class=\"notion-course\"><p>Doivent être traités comme contacts les <strong>personnes vivant sous le même toit</strong> que le cas index et ses <strong><span class=\"nc-red nc-bold\">partenaires sexuels</span></strong>, qu'ils soient symptomatiques ou non.</p></div>"},{"i":"27e14cfec868","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quelles sont les localisations typiques des lésions non spécifiques de grattage dans le cadre d'une gale ?","a":"<div class=\"notion-course\"><ul><li><strong>Espaces interdigitaux</strong>.</li><li>Face antérieure des <strong>poignets et avant-bras</strong>, <strong>coudes</strong>, <strong>aisselles</strong>.</li><li>Région <strong>ombilicale</strong>, <strong>fesses</strong> et face interne des <strong>cuisses</strong>.</li><li><strong>Mamelons/aréoles</strong> chez la femme.</li><li><strong>Organes Génitaux Externes (OGE)</strong>, notamment la verge chez l'homme.</li></ul></div>"},{"i":"3f836379f234","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quels sont les signes évocateurs d'une pédiculose du cuir chevelu ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-pink nc-bold\">pédiculose</span> du cuir chevelu se manifeste par un <strong><span class=\"nc-red nc-bold\">prurit du cuir chevelu</span></strong>, diurne et nocturne, <span class=\"nc-blue_bg\">diffus</span> ou à <span class=\"nc-blue_bg\">prédominance rétro-auriculaire</span>, pouvant s'étendre à la <span class=\"nc-blue_bg\">nuque</span>. On observe également des <span class=\"nc-red nc-bold\">lésions de grattage</span>, une éventuelle <strong><span class=\"nc-purple_bg\">impétiginisation</span></strong> du <span class=\"nc-purple_bg\">cou</span> et des <strong><span class=\"nc-orange_bg\">adénopathies occipitales</span></strong>. Le diagnostic est confirmé par la présence de <strong><span class=\"nc-yellow_bg nc-bold\">poux vivants</span></strong> ou de <strong><span class=\"nc-yellow_bg nc-bold\">lentes</span> <span class=\"nc-yellow_bg nc-bold\">vivantes</span></strong> (<span class=\"nc-blue_bg\">œufs</span> brillants, non coulissants, collés au cheveu, surtout rétro-auriculaires).</p></div>"},{"i":"466b8571edd2","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quelles sont les lésions spécifiques de la gale, leur aspect et leur topographie ?","a":"<div class=\"notion-course\"><ul><li>Le <strong>sillon scabieux</strong> : lésion sinueuse de quelques millimètres, souvent aux <span class=\"nc-blue nc-bold\">espaces interdigitaux</span> et <span class=\"nc-blue nc-bold\">face antérieure des poignets</span>, correspondant au trajet de l'acarien femelle avec une <strong><span class=\"nc-yellow_bg\">éminence acarienne</span></strong> à une extrémité.</li><li>La <strong>vésicule perlée</strong> : petite élevure translucide sur <span class=\"nc-blue nc-bold\">base érythémateuse</span>, typiquement aux <span class=\"nc-blue nc-bold\">espaces interdigitaux</span>.</li><li>Le <strong>nodule scabieux</strong> : papulo-nodule rouge ou violacé, <span class=\"nc-blue\">prurigineux</span>, parfois excorié, surtout au niveau des <span class=\"nc-blue nc-bold\">régions génitales de l'homme</span>.</li></ul></div>"},{"i":"60d308efc8cf","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Comment évoquer une pédiculose corporelle ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-pink nc-bold\">pédiculose</span> corporelle se manifeste par un <strong><span class=\"nc-red nc-bold\">prurit intense</span></strong>, des <span class=\"nc-red nc-bold\">excoriations</span> et une <span class=\"nc-red nc-bold\">éruption maculo-papuleuse</span> prédominant au <strong><span class=\"nc-blue_bg\">dos</span></strong>, au <strong><span class=\"nc-blue_bg\">thorax</span></strong> et à la <span class=\"nc-blue_bg\">racine des membres</span>. En cas d'infestation chronique, une <strong><span class=\"nc-yellow_bg\">leucomélanodermie</span></strong> peut apparaitre. Le diagnostic de certitude repose sur la présence de <span class=\"nc-purple nc-bold\">poux</span> et de <span class=\"nc-purple nc-bold\">lentes</span>, principalement sur les <strong>coutures des vêtements</strong>.</p></div>"},{"i":"921168ebb47c","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quels sont les signes cliniques évocateurs d'une phtiriase pubienne ?","a":"<div class=\"notion-course\"><p>La phtiriase pubienne est évoquée par un <strong><span class=\"nc-red nc-bold\">prurit pubien</span></strong> intense et des <span class=\"nc-blue_bg\">lésions de grattage</span> du pubis et de l'hypogastre. Au diagnostic, on recherche la présence de <strong><span class=\"nc-purple_bg\">lentes</span> grisâtres</strong> et de <strong><span class=\"nc-purple_bg\">poux</span> <span class=\"nc-red nc-bold\">immobiles</span></strong> à la base des poils pubiens.</p></div>"},{"i":"a8af850234b9","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quel est le piège classique à connaître concernant le diagnostic de la gale et des pédiculoses ?","a":"<div class=\"notion-course\"><ul><li>Il faut penser à la <strong>gale devant tout prurit</strong>, même pauci-lésionnel.</li><li>Tout <strong>impétigo de l'adulte</strong> doit faire rechercher une gale.</li><li>Tout <strong>impétigo de la <span class=\"nc-blue_bg\">nuque</span> ou du cuir chevelu</strong> doit faire rechercher une <span class=\"nc-pink nc-bold\">pédiculose</span>.</li></ul></div>"},{"i":"f82c8b95e439","n":171,"o":"171-4","u":"Diagnostic positif","t":"Connaître les signes évocateurs de gale et de pédiculoses","q":"Quel est le symptôme cardinal de la gale typique et ses caractéristiques principales ?","a":"<div class=\"notion-course\"><p>Le symptôme cardinal de la gale typique est un <strong><span class=\"nc-red_bg\">prurit diffus à recrudescence nocturne</span></strong>. Il <span class=\"nc-green_bg\">épargne</span> typiquement le <strong><span class=\"nc-green_bg nc-bold\">visage</span></strong> et a souvent un caractère <strong>conjugal ou familial</strong>.</p></div>"},{"i":"1230359002d3","n":171,"o":"171-6","u":"Contenu multimédia","t":"Photographie de lésions de gale","q":"Décrivez les caractéristiques des nodules scabieux et des vésicules perlées, deux lésions observées dans la gale.","a":"<div class=\"notion-course\">Les <strong>nodules scabieux</strong> sont des <strong>papulo-nodules rouges</strong> de <strong>5 à 10 mm</strong> de diamètre, localisés préférentiellement sur la <strong>verge</strong>, le scrotum, les aisselles ou les aréoles mammaires. Les <strong>vésicules perlées</strong> sont de petites <strong>élevures translucides</strong> reposant sur une <strong>base érythémateuse</strong>, fréquemment observées sur les poignets et les avant-bras.</div>"},{"i":"4f00da2f2d8d","n":171,"o":"171-6","u":"Contenu multimédia","t":"Photographie de lésions de gale","q":"Décrivez les particularités cliniques de la gale hyperkératosique et son impact sur la contagiosité.","a":"<div class=\"notion-course\">La gale hyperkératosique se caractérise par des <strong>placards érythémato-squameux étendus</strong>, souvent généralisés et d'aspect pseudo-psoriasique ou eczématiforme. Elle présente une <strong>contagiosité majeure</strong> en raison du nombre très élevé de parasites présents sur la peau du patient.</div>"},{"i":"8f841dd2ffaf","n":171,"o":"171-6","u":"Contenu multimédia","t":"Photographie de lésions de gale","q":"Comment se manifeste un sillon scabieux, lésion typique de la gale, et quelle est son origine ?","a":"<div class=\"notion-course\">Le sillon scabieux se manifeste comme une <strong>lésion sinueuse</strong> de quelques millimètres de long, le plus fréquemment dans un <strong>espace interdigital</strong>. Il correspond au tunnel creusé sous la couche cornée par l'<strong>acarien femelle</strong> (<em>Sarcoptes scabiei hominis</em>) pour pondre ses œufs.</div>"},{"i":"de2ef3784def","n":171,"o":"171-6","u":"Contenu multimédia","t":"Photographie de lésions de gale","q":"Quelle est la description des lésions cutanées typiques de la gale et leur localisation préférentielle ?","a":"<div class=\"notion-course\">Les lésions cutanées typiques de la gale sont :\n<ul>\n<li>Le <strong>sillon scabieux</strong>, souvent trouvé dans les <strong><span class=\"nc-blue nc-bold\">espaces interdigitaux</span></strong>.</li>\n<li>Les <strong>vésicules perlées</strong>, fréquentes sur les <strong>poignets</strong> et les <strong>avant-bras</strong>.</li>\n<li>Les <strong><span class=\"nc-blue_bg\">nodules scabieux</span></strong>, classiquement observés sur la <strong>verge</strong> chez l'homme.</li>\n<li>La <strong>gale hyperkératosique</strong>, caractérisée par des <strong>placards érythémato-squameux étendus</strong>, souvent localisés sur les paumes, les plantes, ou le tronc.</li>\n</ul></div>"},{"i":"39591d070888","n":171,"o":"171-7","u":"Contenu multimédia","t":"Photographie d’une pédiculose du cuir chevelu","q":"Comment différencier une lente viable d'une lente non viable lors de l'examen clinique d'une pédiculose du cuir chevelu ?","a":"<div class=\"notion-course\"><p>Une lente est considérée comme non viable si elle est située à <strong>plus d'1 cm de l'émergence du cheveu</strong>, indiquant que le cheveu a déjà beaucoup poussé et que la lente est ancienne et probablement vide.</p></div>"},{"i":"a4d6660bbf57","n":171,"o":"171-7","u":"Contenu multimédia","t":"Photographie d’une pédiculose du cuir chevelu","q":"Quelle est la localisation prédominante des lentes observées lors d'une pédiculose du cuir chevelu ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-yellow_bg nc-bold\">lentes</span> sont observées avec une <span class=\"nc-blue_bg\">prédominance </span><strong><span class=\"nc-blue_bg\">rétro-auriculaire</span></strong> (derrière les oreilles).</p></div>"},{"i":"b07660e2778d","n":171,"o":"171-7","u":"Contenu multimédia","t":"Photographie d’une pédiculose du cuir chevelu","q":"Quelle est la caractéristique morphologique des lentes (œufs de poux) de la pédiculose du cuir chevelu ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-yellow_bg nc-bold\">lentes</span> sont des <strong>œufs blanc-grisâtres</strong>, de forme allongée, <strong>collés fermement à la tige pilaire</strong>. Elles ne coulissent pas le long du cheveu, contrairement aux pellicules.</p></div>"},{"i":"e39df39c8ba1","n":171,"o":"171-7","u":"Contenu multimédia","t":"Photographie d’une pédiculose du cuir chevelu","q":"Quel élément permet de poser le diagnostic de certitude d'une pédiculose du cuir chevelu ?","a":"<div class=\"notion-course\"><p>Le diagnostic de certitude d'une <span class=\"nc-pink nc-bold\">pédiculose</span> du cuir chevelu est posé par la découverte de <strong><span class=\"nc-purple nc-bold\">poux</span> adultes vivants</strong>, qui sont bruns, <span class=\"nc-red nc-bold\">allongés</span> et mobiles.</p></div>"},{"i":"022610f215df","n":171,"o":"171-8","u":"Examens complémentaires","t":"Connaître l’association d’un bilan d’infections sexuellement transmissibles (IST) au diagnostic de gale ou pédiculose de corps ou de pubis","q":"Dans quel contexte clinique, face à un diagnostic de gale ou de pédiculose, une recherche systématique d'autres Infections Sexuellement Transmissibles (IST) doit-elle être envisagée ?","a":"<div class=\"notion-course\"><p>Une recherche systématique d'autres <span class=\"nc-red nc-bold\">IST</span> doit être menée devant une <strong>gale du <span class=\"nc-red nc-bold\">pubis</span></strong>, une <strong>phtiriase pubienne</strong> ou une <strong>gale survenue dans un contexte de rapports sexuels à risque</strong>.</p></div>"},{"i":"5cb7ebe04a40","n":171,"o":"171-8","u":"Examens complémentaires","t":"Connaître l’association d’un bilan d’infections sexuellement transmissibles (IST) au diagnostic de gale ou pédiculose de corps ou de pubis","q":"Comment doit être conduite la prise en charge des partenaires sexuels face au diagnostic d'une gale du pubis ou d'une phtiriase pubienne ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-red nc-bold\">partenaires sexuels</span> doivent être systématiquement <strong>dépistés et traités</strong>.</p></div>"},{"i":"962b6451cb73","n":171,"o":"171-8","u":"Examens complémentaires","t":"Connaître l’association d’un bilan d’infections sexuellement transmissibles (IST) au diagnostic de gale ou pédiculose de corps ou de pubis","q":"Existe-t-il un bilan biologique spécifique pour le diagnostic de la gale ou de la pédiculose ?","a":"<div class=\"notion-course\"><p>Non, il n'existe <strong>pas de signe biologique spécifique</strong> ou de bilan biologique propre à la gale ou à la <span class=\"nc-pink nc-bold\">pédiculose</span>. Le bilan est orienté vers la recherche d'<strong>IST associées</strong> si le contexte le justifie.</p></div>"},{"i":"55ab387ed4f0","n":171,"o":"171-1","u":"Épidémiologie","t":"Connaître les modes de transmission principaux et l’épidémiologie de la gale et des pédiculoses","q":"Quels sont les points essentiels concernant les modes de transmission principaux et l’épidémiologie de la gale et des pédiculoses ?","a":"<div class=\"notion-course\"><p>La <span>gale</span> est une <span><span class=\"nc-red nc-bold\">ectoparasitose</span> humaine</span>\n      responsable d'une dermatose fréquente, <strong><span class=\"nc-red nc-bold\">endémo-épidémique mondiale</span> en recrudescence</strong>.\n      L'<strong>homme est le seul réservoir</strong>. <span>Les</span> <span>pédiculoses</span> sont des\n      ectoparasitoses <strong>strictement humaines et <span class=\"nc-red nc-bold\">ubiquitaires</span></strong>.</p>\n      <table>\n        <thead>\n          <tr><th>Entité</th><th>Transmission directe</th><th>Transmission indirecte</th><th><span>Terrain</span> / contexte</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Gale</span></strong></td>\n            <td><span>Interhumaine ++</span> : 1 <span><span class=\"nc-green_bg nc-bold\">contact</span></span> suffit ; contacts intimes et prolongés (familial, couple)</td>\n            <td><span>Rare</span> (linge, literie) — sauf formes <span><span class=\"nc-orange_bg\">profuses</span></span><span class=\"nc-orange_bg\"> et </span><span><span class=\"nc-orange_bg\">hyperkératosiques</span></span></td>\n            <td>Collectivités médicalisées, foyers de personnes âgées, milieux défavorisés, <span class=\"nc-orange_bg\">immunodéprimés</span> ; <span>gale</span> du <strong><span class=\"nc-red nc-bold\">pubis</span> = <span><span class=\"nc-red nc-bold\">IST</span></span></strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Pédiculose</span> du cuir chevelu</strong></td>\n            <td><span>Interhumaine ++</span> (<span>contact</span> des têtes)</td>\n            <td>Possible (bonnets, peignes, brosses)</td>\n            <td><strong><span class=\"nc-red nc-bold\">Collectivités d'enfants</span></strong> en milieu scolaire — <strong>tous <span>les</span> milieux sociaux</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Pédiculose corporelle</strong></td>\n            <td><span>Interhumaine</span></td>\n            <td><span>++</span> (vêtements)</td>\n            <td><span>Marqueur de <span class=\"nc-red nc-bold\">précarité</span></span> : camps de réfugiés, prisons, SDF (<span class=\"nc-red nc-bold\">manque d'hygiène</span> + <span class=\"nc-red nc-bold\">froid</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Phtiriase pubienne</strong></td>\n            <td><span>Sexuelle</span></td>\n            <td>—</td>\n            <td><strong><span>IST</span></strong> — penser au <span>dépistage</span> des autres IST</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span>IST</span> · 59 — Sujet en situation de précarité</em></p></div>"},{"i":"6423fc558668","n":171,"o":"171-2","u":"Physiopathologie","t":"Connaître la physiopathologie de la gale","q":"Quels sont les points essentiels concernant la physiopathologie de la gale ?","a":"<div class=\"notion-course\"><p>Agent : <span>Sarcoptes scabiei var. hominis</span>, un <strong>acarien</strong>.\n      Ce sont <span>les</span> <strong><span class=\"nc-red nc-bold\">femelles</span></strong> qui sont responsables de la maladie.</p>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>Mobilité</td><td>Déplacement de <span>plusieurs cm/h</span> à la surface de la peau ; bonne mobilité à <span>25-30 °C</span>, perte de mobilité <span><span class=\"nc-red nc-bold\">&lt; 20 °C</span></span></td></tr>\n          <tr><td>Destruction thermique</td><td>Survie hors de l’hôte : plusieurs jours possibles, selon température et humidité ; appliquer le protocole de décontamination adapté.</td></tr>\n          <tr><td>Incubation</td><td><span>≈ 3 semaines</span> — plus courte si réinfestation (<span>5 j à 1 mois</span>)</td></tr>\n          <tr><td>Cycle <span>parasitaire</span></td><td><span>≈ <span class=\"nc-pink nc-bold\">20 jours</span></span></td></tr>\n          <tr><td>Charge <span>parasitaire</span></td><td><span>10-20 <span class=\"nc-red nc-bold\">femelles</span></span> par individu (<span>gale</span> commune)</td></tr>\n        </tbody>\n      </table>\n      <p>Le mécanisme se déroule en trois temps :</p>\n      <ul>\n        <li>La <strong><span class=\"nc-pink nc-bold\">femelle</span></strong> creuse un <span>tunnel (sillon)</span> dans la <span>couche cornée</span> de l'épiderme et y <strong>pond ses <span class=\"nc-blue_bg\">œufs</span></strong>.</li>\n        <li>La <span><span class=\"nc-yellow_bg\">réaction urticarienne</span></span> de l'hôte est responsable du <strong><span><span class=\"nc-red nc-bold\">prurit</span></span></strong>.</li>\n        <li>Le grattage expose au <span class=\"nc-red_bg\">risque de</span> <span><span class=\"nc-red_bg nc-bold\">surinfection bactérienne</span></span>.</li>\n      </ul></div>"},{"i":"ab91232af11a","n":171,"o":"171-3","u":"Physiopathologie","t":"Connaître les différents agents des pédiculoses","q":"Quels sont les points essentiels concernant les différents agents des pédiculoses ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-purple nc-bold\">poux</span> de tête et du pubis restent attachés à leurs sites pileux ; le pou de corps vit surtout dans les vêtements et gagne la peau pour se nourrir.</p>\n      <table>\n        <thead><tr><th>Espèce</th><th>Nom courant</th><th>Localisation / mobilité</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-purple_bg\">Pediculus humanus capitis</span></span></td><td>Pou de tête</td><td>Cuir chevelu — <strong>très mobile</strong></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Pediculus humanus corporis</span></span></td><td>Pou de corps</td><td>Corps ; se réfugie dans <span>les</span> vêtements — <strong>très mobile</strong></td></tr>\n          <tr><td><span><span class=\"nc-purple_bg\">Phtirus pubis</span></span> (<span class=\"nc-purple_bg\">Phtirius inguinalis</span>)</td><td>Pou du pubis / <span>morpion</span></td><td>Région génitale — <strong>vit accroché aux poils</strong> (immobile)</td></tr>\n        </tbody>\n      </table>\n      \n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span>IST</span></em></p></div>"},{"i":"3c6b431a7f8a","n":171,"o":"171-5","u":"Diagnostic positif","t":"Connaître les signes atypiques de gale et de pédiculoses","q":"Quels sont les points essentiels concernant les signes atypiques de gale et de pédiculoses ?","a":"<div class=\"notion-course\"><h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Gale</span> — formes cliniques particulières</h4>\n      <table>\n        <thead><tr><th>Forme</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span>Gale</span> du nourrisson</strong></td><td><strong>Atteinte possible du <span class=\"nc-red nc-bold\">visage</span></strong> ; <span><span class=\"nc-blue_bg\">vésico-pustules</span> palmo-<span class=\"nc-red nc-bold\">plantaires</span></span> ; <strong><span class=\"nc-blue_bg\">nodules scabieux</span> <span class=\"nc-red nc-bold\">péri-axillaires</span></strong> (et non génitaux comme chez l'adulte)</td></tr>\n          <tr><td><strong><span>Gale</span> profuse</strong></td><td><span>Éruption</span> profuse et étendue, <strong>y compris le <span class=\"nc-blue_bg\">dos</span></strong> ; <span>terrain</span> : personne âgée alitée, troubles des fonctions supérieures<br>Causes : diagnostic tardif ; déficit immunitaire (<span><span class=\"nc-purple_bg\">VIH</span></span> ++) ; traitement inadapté (<span>corticothérapie</span>)</td></tr>\n          <tr><td><strong><span>Gale</span> hyperkératosique</strong></td><td><span>Terrain</span> : <span class=\"nc-orange_bg\">immunodéprimés</span> ou sujets âgés sous <span>immunosuppresseurs</span> (<span>corticothérapie</span>) ; <span><span class=\"nc-red nc-bold\">contagiosité majeure</span></span> (prolifération <span>parasitaire</span> intense) ; <span>prurit</span> discret voire absent ; atteinte de tout le corps y compris <span class=\"nc-blue_bg\">visage</span>, <span class=\"nc-blue_bg\">cuir chevelu</span> et <strong>ongles</strong>, voire <span>érythrodermie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes compliquées</strong> : <span>impétiginisation</span> (cause majeure de\n      <span><span class=\"nc-red\">RAA</span></span> et de <span>glomérulonéphrite post-streptococcique</span>\n      dans <span>les</span> pays en développement) ; <span class=\"nc-orange_bg\">eczématisation</span> (secondaire à la <span>gale</span> ou à son traitement).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"nc-blue_bg\">Nodules scabieux</span> <span>vs</span> post-scabieux (à distinguer)</h4>\n      <table>\n        <thead><tr><th></th><th><span class=\"nc-blue_bg\">Nodules scabieux</span></th><th><span class=\"nc-orange_bg\">Nodules post-scabieux</span></th></tr></thead>\n        <tbody>\n          <tr><td>Siège</td><td>Régions génitales</td><td>Ubiquitaire</td></tr>\n          <tr><td>Aspect</td><td>Papulo-nodules rouges/violets</td><td>Papulo-nodules rouges/cuivrés</td></tr>\n          <tr><td>Sarcopte</td><td><strong>En contiennent</strong></td><td><strong>N'en contiennent pas</strong> — réaction immuno-<span>allergique</span></td></tr>\n          <tr><td><span>Évolution</span></td><td>Régressent avec le traitement</td><td><span>Persistent plusieurs semaines après un traitement efficace</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> <span>Les</span> <strong><span class=\"nc-orange_bg\">nodules post-scabieux</span></strong>\n      qui persistent après traitement ne contiennent pas de sarcopte et <span>ne justifient pas\n      un retraitement</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculose corporelle — infections transmises par le pou de corps</h4>\n      <ul>\n        <li><strong><span><span class=\"nc-red_bg\">Fièvre</span></span><span class=\"nc-red_bg\"> récurrente cosmopolite</span></strong> — <span><span class=\"nc-purple_bg\">Borrelia recurrentis</span></span>.</li>\n        <li><strong>Typhus exanthématique (épidémique)</strong> — <span>Rickettsia prowazekii</span> (à ne pas confondre avec la <span>fièvre</span> typhoïde).</li>\n        <li><strong><span><span class=\"nc-red_bg\">Fièvre</span></span><span class=\"nc-red_bg\"> des tranchées</span></strong> — <span><span class=\"nc-purple_bg\">Bartonella quintana</span></span> : recrudescence chez <span>les</span> sujets précaires et <span><span class=\"nc-red nc-bold\">alcooliques</span></span> des métropoles ; responsable de <span><span class=\"nc-red nc-bold\">septicémie</span></span> et d'<span><span class=\"nc-red nc-bold\">endocardite</span></span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span>VIH</span> · 152 — <span>Endocardite</span> infectieuse · 261 — Néphropathie glomérulaire</em></p></div>"},{"i":"f2e2008f1ff4","n":171,"o":"171-9","u":"Examens complémentaires","t":"Connaître les indications du diagnostic parasitologique","q":"Quels sont les points essentiels concernant les indications du diagnostic parasitologique ?","a":"<div class=\"notion-course\"><p>Le diagnostic de <span>gale</span> est <strong>avant tout clinique</strong> (anamnèse + topographie évocatrice) ;\n      l'<span>examen parasitologique</span> n'est <strong>pas obl<span>iga</span>toire</strong> pour le poser.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen parasitologique direct — technique</h4>\n      <ul>\n        <li>Gratter un <span>sillon</span> au <strong>vaccinostyle</strong>, en prélevant si possible l'<span><span class=\"nc-yellow_bg\">éminence acarienne</span></span>.</li>\n        <li>Observation au <strong><span class=\"nc-yellow_bg\">microscope</span></strong> : met en évidence <span>les</span> <span><span class=\"nc-blue_bg\">œufs</span></span> ou l'<span>acarien femelle adulte</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications</h4>\n      <ul>\n        <li>Confirmation en cas de <strong>doute diagnostique</strong> ou de forme atypique.</li>\n        <li><strong>Négativation</strong> exigée avant de lever l'éviction des gales <span><span class=\"nc-orange_bg\">profuses</span></span><span class=\"nc-orange_bg\"> et </span><span><span class=\"nc-orange_bg\">hyperkératosiques</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Limite.</strong> La mise en évidence du parasite est\n      <span><span class=\"nc-red nc-bold\">difficile en dehors des formes profuses et hyperkératosiques</span></span> : un examen\n      négatif n'élimine pas une <span>gale</span> commune.</div></div>"},{"i":"001fd3beb35d","n":171,"o":"171-10","u":"Diagnostic positif","t":"Connaître l’intérêt du dermatoscope pour le diagnostic de gale","q":"Quels sont les points essentiels concernant l’intérêt du dermatoscope pour le diagnostic de gale ?","a":"<div class=\"notion-course\"><p>La <span>dermatoscopie</span> est un examen simple et non invasif, réalisable au cabinet.</p>\n      <ul>\n        <li>Elle montre un <span class=\"nc-blue_bg\">aspect caractéristique </span><strong><span class=\"nc-blue_bg\">« en</span> <span><span class=\"nc-blue_bg nc-bold\">deltaplane</span></span> »</strong> : la tête de l'acarien femelle visible à l'extrémité du <span>sillon</span>.</li>\n        <li>Elle permet de <strong>remplacer l'<span>examen parasitologique</span></strong>, peu accessible en pratique de ville.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le diagnostic de <span>gale</span> reste <strong>avant tout\n      clinique</strong> : ni la dermatoscopie ni l'<span>examen parasitologique</span> ne sont obl<span>iga</span>toires pour le poser.</div></div>"},{"i":"f39edf325401","n":171,"o":"171-13","u":"Prise en charge","t":"Connaître les causes d’échec du traitement de la gale et des pédiculoses","q":"Quels sont les points essentiels concernant les causes d’échec du traitement de la gale et des pédiculoses ?","a":"<div class=\"notion-course\"><h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Gale</span> — <span>prurit</span> persistant <span>8-15 jours</span> après le traitement</h4>\n      <p>Un <span>prurit</span> qui persiste n'est pas toujours un échec. Évoquer :</p>\n      <ul>\n        <li><span><span class=\"nc-red nc-bold\">Eczéma de contact</span></span> ; <span><span class=\"nc-red nc-bold\">irritation par le traitement</span></span>.</li>\n        <li><span><span class=\"nc-red nc-bold\">Parasitophobie</span></span> ; autres causes de <span>prurit</span>.</li>\n        <li><strong><span class=\"nc-orange_bg\">Nodules post-scabieux</span></strong> persistants — réaction immuno-<span>allergique</span>, qui <span>ne justifient pas un retraitement</span>.</li>\n      </ul>\n      <p><strong>Échec vrai</strong> (lésions cliniques évocatrices et/ou <span>examen parasitologique</span> positif) :\n      <span><span class=\"nc-red nc-bold\">rechute</span></span> après un traitement inapproprié ; <span class=\"nc-red nc-bold\">rechute</span> liée à une\n      <span><span class=\"nc-red nc-bold\">résistance</span></span> au traitement ; <span><span class=\"nc-red nc-bold\">recontamination</span></span>\n      après guérison.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pédiculoses — causes d'échec</h4>\n      <ul>\n        <li>Incompréhension, ignorance, négligence ; <span>coût</span> (aucune spécialité n'est remboursée).</li>\n        <li><span>Réinfestation</span> à partir de l'environnement.</li>\n        <li>Durée ou fréquence d'utilisation insuffisantes ; <span>quantité de produit insuffisante</span> ; forme galénique inappropriée.</li>\n        <li><span><span class=\"nc-orange_bg\">Acquisition de résistance</span></span><span class=\"nc-orange_bg\"> des poux</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"nc-pink nc-bold\">Pédiculose</span> du <span class=\"nc-blue_bg\">cuir chevelu</span> — examen de contrôle.</strong> <span class=\"nc-yellow_bg nc-bold\">Poux vivants</span>\n      à <span>J2</span> → <span><span class=\"nc-red nc-bold\">résistance</span></span> probable → <strong>changer de\n      classe</strong> pharmacologique. <span class=\"nc-yellow_bg nc-bold\">Poux vivants</span> à <span>J12</span> → <span class=\"nc-red nc-bold\">mauvais effet lenticide</span>\n      → <strong>refaire le produit initial</strong>.</div></div>"},{"i":"40d90d364d6c","n":171,"o":"171-14","u":"Prise en charge","t":"Connaître les modalités de gestion d’une épidémie de gale dans un établissement","q":"Quels sont les points essentiels concernant les modalités de gestion d’une épidémie de gale dans un établissement ?","a":"<div class=\"notion-course\"><ul><li>Confirmer le cas et prévenir l’équipe d’hygiène ; définir exposition, période et type de gale. Les formes <span class=\"nc-red nc-bold\">hyperkératosiques</span> imposent une enquête et un périmètre plus larges.</li><li>Traitement coordonné des cas et contacts selon cercles d’exposition, y compris contacts asymptomatiques indiqués. Traiter tous les visiteurs sans évaluation n’est pas une règle universelle.</li><li>Précautions <span class=\"nc-green_bg nc-bold\">contact</span>, information, linge traité par lavage adapté ou isolement en sac selon recommandations et type de gale. La durée de survie varie avec température/humidité ; 12–24 heures ne constitue pas une garantie.</li><li>Planifier la deuxième prise/application et la surveillance des nouveaux cas. Éviction et levée d’isolement dépendent de la forme et du protocole ; pour une gale hyperkératosique, avis spécialisé et contrôle parasitologique.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181c3a314d9a7b3424dd0?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
